namespace Merkushin\Wpal\Service;

use WP_Comment;
use WP_Error;
use WP_Post;
use WP_Query;
use WP_Rewrite;
use WP_Term;

interface Feeds {
	/**
	 * Displays the atom enclosure for the current post.
	 *
	 * Uses the global $post to check whether the post requires a password and if
	 * the user has the password for the post. If not then it will return before
	 * displaying.
	 *
	 * Also uses the function get_post_custom() to get the post's 'enclosure'
	 * metadata field and parses the value to display the enclosure(s). The
	 * enclosure(s) consist of link HTML tag(s) with a URI and other attributes.
	 *
	 * @since 2.2.0
	 */
	public function atom_enclosure();

	/**
	 * Displays Site Icon in atom feeds.
	 *
	 * @since 4.3.0
	 *
	 * @see get_site_icon_url()
	 */
	public function atom_site_icon();

	/**
	 * Displays RSS container for the bloginfo function.
	 *
	 * You can retrieve anything that you can using the get_bloginfo() function.
	 * Everything will be stripped of tags and characters converted, when the values
	 * are retrieved for use in the feeds.
	 *
	 * @since 0.71
	 *
	 * @see get_bloginfo() For the list of possible values to display.
	 *
	 * @param string $show See get_bloginfo() for possible values.
	 */
	public function bloginfo_rss( $show = '' );

	/**
	 * Displays the current comment author in the feed.
	 *
	 * @since 1.0.0
	 */
	public function comment_author_rss();

	/**
	 * Displays the feed GUID for the current comment.
	 *
	 * @since 2.5.0
	 *
	 * @param int|WP_Comment $comment_id Optional comment object or ID. Defaults to global comment object.
	 */
	public function comment_guid( $comment_id = null );

	/**
	 * Displays the link to the comments.
	 *
	 * @since 1.5.0
	 * @since 4.4.0 Introduced the `$comment` argument.
	 *
	 * @param int|WP_Comment $comment Optional. Comment object or ID. Defaults to global comment object.
	 */
	public function comment_link( $comment = null );

	/**
	 * Displays the current comment content for use in the feeds.
	 *
	 * @since 1.0.0
	 */
	public function comment_text_rss();

	/**
	 * Outputs the link to the comments for the current post in an XML safe way.
	 *
	 * @since 3.0.0
	 */
	public function comments_link_feed();

	/**
	 * Returns the content type for specified feed type.
	 *
	 * @since 2.8.0
	 *
	 * @param string $type Type of feed. Possible values include 'rss', rss2', 'atom', and 'rdf'.
	 * @return string Content type for specified feed type.
	 */
	public function feed_content_type( $type = '' );

	/**
	 * Displays the links to the general feeds.
	 *
	 * @since 2.8.0
	 *
	 * @param array $args Optional arguments.
	 */
	public function feed_links( $args = array() );

	/**
	 * Displays the links to the extra feeds such as category feeds.
	 *
	 * @since 2.8.0
	 *
	 * @param array $args Optional arguments.
	 */
	public function feed_links_extra( $args = array() );

	/**
	 * Builds SimplePie object based on RSS or Atom feed from URL.
	 *
	 * @since 2.8.0
	 *
	 * @param string|string[] $url URL of feed to retrieve. If an array of URLs, the feeds are merged
	 *                             using SimplePie's multifeed feature.
	 *                             See also {@link http://simplepie.org/wiki/faq/typical_multifeed_gotchas}
	 * @return \SimplePie\SimplePie|WP_Error SimplePie object on success or WP_Error object on failure.
	 */
	public function fetch_feed( $url );

	/**
	 * Retrieves the feed link for a given author.
	 *
	 * Returns a link to the feed for all posts by a given author. A specific feed
	 * can be requested or left blank to get the default feed.
	 *
	 * @since 2.5.0
	 *
	 * @param int    $author_id Author ID.
	 * @param string $feed      Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                          Default is the value of get_default_feed().
	 * @return string Link to the feed for the author specified by $author_id.
	 */
	public function get_author_feed_link( $author_id, $feed = '' );

	/**
	 * Retrieves RSS container for the bloginfo function.
	 *
	 * You can retrieve anything that you can using the get_bloginfo() function.
	 * Everything will be stripped of tags and characters converted, when the values
	 * are retrieved for use in the feeds.
	 *
	 * @since 1.5.1
	 *
	 * @see get_bloginfo() For the list of possible values to display.
	 *
	 * @param string $show See get_bloginfo() for possible values.
	 * @return string
	 */
	public function get_bloginfo_rss( $show = '' );

	/**
	 * Retrieves the feed link for a category.
	 *
	 * Returns a link to the feed for all posts in a given category. A specific feed
	 * can be requested or left blank to get the default feed.
	 *
	 * @since 2.5.0
	 *
	 * @param int|WP_Term|object $cat  The ID or category object whose feed link will be retrieved.
	 * @param string             $feed Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                                 Default is the value of get_default_feed().
	 * @return string Link to the feed for the category specified by `$cat`.
	 */
	public function get_category_feed_link( $cat, $feed = '' );

	/**
	 * Retrieves the current comment author for use in the feeds.
	 *
	 * @since 2.0.0
	 *
	 * @return string Comment Author.
	 */
	public function get_comment_author_rss();

	/**
	 * Retrieves the feed GUID for the current comment.
	 *
	 * @since 2.5.0
	 *
	 * @param int|WP_Comment $comment_id Optional comment object or ID. Defaults to global comment object.
	 * @return string|false GUID for comment on success, false on failure.
	 */
	public function get_comment_guid( $comment_id = null );

	/**
	 * Retrieves the default feed.
	 *
	 * The default feed is 'rss2', unless a plugin changes it through the
	 * {@see 'default_feed'} filter.
	 *
	 * @since 2.5.0
	 *
	 * @return string Default feed, or for example 'rss2', 'atom', etc.
	 */
	public function get_default_feed();

	/**
	 * Gets the UTC time of the most recently modified post from WP_Query.
	 *
	 * If viewing a comment feed, the time of the most recently modified
	 * comment will be returned.
	 *
	 * @since 5.2.0
	 *
	 * @global WP_Query $wp_query WordPress Query object.
	 *
	 * @param string $format Date format string to return the time in.
	 * @return string|false The time in requested format, or false on failure.
	 */
	public function get_feed_build_date( $format );

	/**
	 * Retrieves the permalink for the feed type.
	 *
	 * @since 1.5.0
	 *
	 * @global WP_Rewrite $wp_rewrite WordPress rewrite component.
	 *
	 * @param string $feed Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                     Default is the value of get_default_feed().
	 * @return string The feed permalink.
	 */
	public function get_feed_link( $feed = '' );

	/**
	 * Retrieves the permalink for the post comments feed.
	 *
	 * @since 2.2.0
	 *
	 * @param int    $post_id Optional. Post ID. Default is the ID of the global `$post`.
	 * @param string $feed    Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                        Default is the value of get_default_feed().
	 * @return string The permalink for the comments feed for the given post on success, empty string on failure.
	 */
	public function get_post_comments_feed_link( $post_id = 0, $feed = '' );

	/**
	 * Retrieves the permalink for a post type archive feed.
	 *
	 * @since 3.1.0
	 *
	 * @param string $post_type Post type.
	 * @param string $feed      Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                          Default is the value of get_default_feed().
	 * @return string|false The post type feed permalink. False if the post type
	 *                      does not exist or does not have an archive.
	 */
	public function get_post_type_archive_feed_link( $post_type, $feed = '' );

	/**
	 * Retrieves the permalink for the search results comments feed.
	 *
	 * @since 2.5.0
	 *
	 * @global WP_Rewrite $wp_rewrite WordPress rewrite component.
	 *
	 * @param string $search_query Optional. Search query. Default empty.
	 * @param string $feed         Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                             Default is the value of get_default_feed().
	 * @return string The comments feed search results permalink.
	 */
	public function get_search_comments_feed_link( $search_query = '', $feed = '' );

	/**
	 * Retrieves the permalink for the search results feed.
	 *
	 * @since 2.5.0
	 *
	 * @global WP_Rewrite $wp_rewrite WordPress rewrite component.
	 *
	 * @param string $search_query Optional. Search query. Default empty.
	 * @param string $feed         Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                             Default is the value of get_default_feed().
	 * @return string The search results feed permalink.
	 */
	public function get_search_feed_link( $search_query = '', $feed = '' );

	/**
	 * Returns the link for the currently displayed feed.
	 *
	 * @since 5.3.0
	 *
	 * @return string Correct link for the atom:self element.
	 */
	public function get_self_link();

	/**
	 * Retrieves the permalink for a tag feed.
	 *
	 * @since 2.3.0
	 *
	 * @param int|WP_Term|object $tag  The ID or term object whose feed link will be retrieved.
	 * @param string             $feed Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                                 Default is the value of get_default_feed().
	 * @return string                  The feed permalink for the given tag.
	 */
	public function get_tag_feed_link( $tag, $feed = '' );

	/**
	 * Retrieves the feed link for a term.
	 *
	 * Returns a link to the feed for all posts in a given term. A specific feed
	 * can be requested or left blank to get the default feed.
	 *
	 * @since 3.0.0
	 *
	 * @param int|WP_Term|object $term     The ID or term object whose feed link will be retrieved.
	 * @param string             $taxonomy Optional. Taxonomy of `$term_id`.
	 * @param string             $feed     Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                                     Default is the value of get_default_feed().
	 * @return string|false Link to the feed for the term specified by `$term` and `$taxonomy`.
	 */
	public function get_term_feed_link( $term, $taxonomy = '', $feed = '' );

	/**
	 * Retrieves all of the post categories, formatted for use in feeds.
	 *
	 * All of the categories for the current post in the feed loop, will be
	 * retrieved and have feed markup added, so that they can easily be added to the
	 * RSS2, Atom, or RSS1 and RSS0.91 RDF feeds.
	 *
	 * @since 2.1.0
	 *
	 * @param string $type Optional, default is the type returned by get_default_feed().
	 * @return string All of the post categories for displaying in the feed.
	 */
	public function get_the_category_rss( $type = null );

	/**
	 * Retrieves the post content for feeds.
	 *
	 * @since 2.9.0
	 *
	 * @see get_the_content()
	 *
	 * @param string $feed_type The type of feed. rss2 | atom | rss | rdf
	 * @return string The filtered content.
	 */
	public function get_the_content_feed( $feed_type = null );

	/**
	 * Retrieves the current post title for the feed.
	 *
	 * @since 2.0.0
	 * @since 6.6.0 Added the `$post` parameter.
	 *
	 * @param int|WP_Post $post Optional. Post ID or WP_Post object. Default is global $post.
	 * @return string Current post title.
	 */
	public function get_the_title_rss( $post = 0 );

	/**
	 * Retrieves the blog title for the feed title.
	 *
	 * @since 2.2.0
	 * @since 4.4.0 The optional `$sep` parameter was deprecated and renamed to `$deprecated`.
	 *
	 * @param string $deprecated Unused.
	 * @return string The document title.
	 */
	public function get_wp_title_rss( $deprecated = '&#8211;' );

	/**
	 * Displays the HTML type based on the blog setting.
	 *
	 * The two possible values are either 'xhtml' or 'html'.
	 *
	 * @since 2.2.0
	 */
	public function html_type_rss();

	/**
	 * Displays the comment feed link for a post.
	 *
	 * Prints out the comment feed link for a post. Link text is placed in the
	 * anchor. If no link text is specified, default text is used. If no post ID is
	 * specified, the current post is used.
	 *
	 * @since 2.5.0
	 *
	 * @param string $link_text Optional. Descriptive link text. Default 'Comments Feed'.
	 * @param int    $post_id   Optional. Post ID. Default is the ID of the global `$post`.
	 * @param string $feed      Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                          Default is the value of get_default_feed().
	 */
	public function post_comments_feed_link( $link_text = '', $post_id = 0, $feed = '' );

	/**
	 * Determines the type of a string of data with the data formatted.
	 *
	 * Tell whether the type is text, HTML, or XHTML, per RFC 4287 section 3.1.
	 *
	 * In the case of WordPress, text is defined as containing no markup,
	 * XHTML is defined as "well formed", and HTML as tag soup (i.e., the rest).
	 *
	 * Container div tags are added to XHTML values, per section 3.1.1.3.
	 *
	 * @link http://www.atomenabled.org/developers/syndication/atom-format-spec.php#rfc.section.3.1
	 *
	 * @since 2.5.0
	 *
	 * @param string $data Input string.
	 * @return array array(type, value)
	 */
	public function prep_atom_text_construct( $data );

	/**
	 * Displays Site Icon in RSS2.
	 *
	 * @since 4.3.0
	 */
	public function rss2_site_icon();

	/**
	 * Displays the rss enclosure for the current post.
	 *
	 * Uses the global $post to check whether the post requires a password and if
	 * the user has the password for the post. If not then it will return before
	 * displaying.
	 *
	 * Also uses the function get_post_custom() to get the post's 'enclosure'
	 * metadata field and parses the value to display the enclosure(s). The
	 * enclosure(s) consist of enclosure HTML tag(s) with a URI and other
	 * attributes.
	 *
	 * @since 1.5.0
	 */
	public function rss_enclosure();

	/**
	 * Displays the link for the currently displayed feed in a XSS safe way.
	 *
	 * Generate a correct link for the atom:self element.
	 *
	 * @since 2.5.0
	 */
	public function self_link();

	/**
	 * Displays the post categories in the feed.
	 *
	 * @since 0.71
	 *
	 * @see get_the_category_rss() For better explanation.
	 *
	 * @param string $type Optional, default is the type returned by get_default_feed().
	 */
	public function the_category_rss( $type = null );

	/**
	 * Displays the post content for feeds.
	 *
	 * @since 2.9.0
	 *
	 * @param string $feed_type The type of feed. rss2 | atom | rss | rdf
	 */
	public function the_content_feed( $feed_type = null );

	/**
	 * Displays the post excerpt for the feed.
	 *
	 * @since 0.71
	 */
	public function the_excerpt_rss();

	/**
	 * Displays the permalink for the feed type.
	 *
	 * @since 3.0.0
	 *
	 * @param string $anchor The link's anchor text.
	 * @param string $feed   Optional. Feed type. Possible values include 'rss2', 'atom'.
	 *                       Default is the value of get_default_feed().
	 */
	public function the_feed_link( $anchor, $feed = '' );

	/**
	 * Displays the permalink to the post for use in feeds.
	 *
	 * @since 2.3.0
	 */
	public function the_permalink_rss();

	/**
	 * Displays the post title in the feed.
	 *
	 * @since 0.71
	 */
	public function the_title_rss();

	/**
	 * Displays the blog title for display of the feed title.
	 *
	 * @since 2.2.0
	 * @since 4.4.0 The optional `$sep` parameter was deprecated and renamed to `$deprecated`.
	 *
	 * @param string $deprecated Unused.
	 */
	public function wp_title_rss( $deprecated = '&#8211;' );
}
